# ---------------------------------------------------------------- basis / Cartier

def basis_list(D):
    return [(a, b) for b in (_sage_const_1 , _sage_const_2 , _sage_const_3 ) for a in range(D * b // _sage_const_4 )]

def cartier_matrix(p, fpol, D, perturb=None):
    """Matrix of the Cartier operator on H^0(Omega) in the graded basis.
       Returns (M, B, outside) ; outside = nonzero image coeffs landing off-basis."""
    B = basis_list(D)
    idx = {ab: j for j, ab in enumerate(B)}
    M = matrix(GF(p), len(B), len(B))
    x = fpol.parent().gen()
    outside = []
    for j, (a, b) in enumerate(B):
        k = min(kk for kk in range(_sage_const_4 ) if (p * kk + b) % _sage_const_4  == _sage_const_0 )
        t = (b + p * k) // _sage_const_4 
        if perturb and b in perturb:
            t += perturb[b]
        e = p - t
        if e < _sage_const_0 :
            raise RuntimeError("negative exponent p-t at p=%d b=%d" % (p, b))
        g = x**a * fpol**e
        bp = _sage_const_4  - k
        dg = g.degree()
        i = _sage_const_0 
        while i * p + p - _sage_const_1  <= dg:
            c = g[i * p + p - _sage_const_1 ]           # p-th root is the identity on F_p
            if c != _sage_const_0 :
                if (i, bp) in idx:
                    M[idx[(i, bp)], j] = c
                else:
                    outside.append(((a, b), (i, bp), c))
            i += _sage_const_1 
    return M, B, outside

def new_block(M, B):
    ni = [j for j, (a, b) in enumerate(B) if b in (_sage_const_1 , _sage_const_3 )]
    return M.matrix_from_rows_and_columns(ni, ni)

# ---------------------------------------------------------------- point counts

_tab_cache = {}
def power_tables(F):
    key = F.cardinality()
    if key not in _tab_cache:
        s4, s2 = set(), set()
        for w in F:
            s4.add(w**_sage_const_4 ); s2.add(w**_sage_const_2 )
        g4 = gcd(_sage_const_4 , key - _sage_const_1 ); g2 = _sage_const_2 
        _tab_cache[key] = (s4, s2, g4, g2)
    return _tab_cache[key]

def counts(F, fco):
    """(#C, #E) over F for C: w^4=f, E: y^2=f ; one point at infinity each (gcd(4,D)=1, D odd)."""
    s4, s2, g4, g2 = power_tables(F)
    nC = _sage_const_1 ; nE = _sage_const_1 
    for x in F:
        v = F(_sage_const_0 )
        for c in reversed(fco):
            v = v * x + F(c)
        if v == _sage_const_0 :
            nC += _sage_const_1 ; nE += _sage_const_1 
        else:
            if v in s4: nC += g4
            if v in s2: nE += g2
    return nC, nE

# ---------------------------------------------------------------- iso classes (M-6)

def cover_class(p, fco):
    """Canonical label of the cover w^4 = f under x->alpha*x+beta and 4th-power scaling."""
    Fp = GF(p); R = PolynomialRing(Fp, 'x'); x = R.gen()
    f = R([Fp(c) for c in fco]); a3 = f[_sage_const_3 ]
    f = f / a3
    f = f(x - f[_sage_const_2 ] / _sage_const_3 )                       # depress
    P, Q = f[_sage_const_1 ], f[_sage_const_0 ]
    g = gcd(_sage_const_4 , p - _sage_const_1 ); z = Fp.multiplicative_generator()**((p - _sage_const_1 ) // g)
    def coset(u):
        v = u**((p - _sage_const_1 ) // g)
        for e in range(g):
            if z**e == v: return e
        raise RuntimeError
    best = None
    for al in Fp:
        if al == _sage_const_0 : continue
        cand = (ZZ(P / al**_sage_const_2 ), ZZ(Q / al**_sage_const_3 ), coset(a3 * al**_sage_const_3 ))
        if best is None or cand < best: best = cand
    return best

# ---------------------------------------------------------------- C3 divisors

def c3_divisors(p, fco, D):
    K = FunctionField(GF(p), 'x'); x = K.gen()
    R = PolynomialRing(K, 'T'); T = R.gen()
    fx = sum(K(int(c)) * x**i for i, c in enumerate(fco))
    L = K.extension(T**_sage_const_4  - fx, 'w'); w = L.gen()
    dxL = L(x).differential()
    want = [((_sage_const_0 ,_sage_const_1 ), False), ((_sage_const_0 ,_sage_const_2 ), True), ((_sage_const_1 ,_sage_const_2 ), False),
            ((_sage_const_0 ,_sage_const_3 ), True), ((_sage_const_1 ,_sage_const_3 ), True), ((_sage_const_2 ,_sage_const_3 ), False)]
    got = []
    for (a, b), _ in want:
        om = (L(x)**a / w**b) * dxL
        Dv = om.divisor()
        sup = Dv.support()
        mn = min([Dv.multiplicity(Pt) for Pt in sup]) if sup else _sage_const_0 
        got.append(((a, b), bool(mn >= _sage_const_0 )))
    return (got == want), L.genus(), got

# ---------------------------------------------------------------- driver

def run_arm(name, primes_list, D, rng, do_c3, do_c5, log):
    rows = []
    for p in primes_list:
        Fp = GF(p); R = PolynomialRing(Fp, 'x'); x = R.gen()
        cubics = []
        if D == _sage_const_3 :
            for nm, co in CURATED:
                cubics.append((nm, co, "blind"))   # prereg v3 sec.1: never run at these primes
        drawn = _sage_const_0 ; tries = _sage_const_0 
        while drawn < N_RANDOM and tries < _sage_const_500 :
            tries += _sage_const_1 
            co = [rng.randrange(p) for _ in range(D)] + [rng.randrange(_sage_const_1 , p)]
            fp = R([Fp(c) for c in co])
            if fp.discriminant() == _sage_const_0 : continue
            cubics.append(("rand%d_%s" % (drawn, "".join(str(c) for c in co)), co, "blind"))
            drawn += _sage_const_1 
        for nm, co, blindness in cubics:
            fp = R([Fp(c) for c in co])
            if fp.discriminant() == _sage_const_0 :
                log.append(("EXCLUDED", p, nm))
                continue
            M, B, outside = cartier_matrix(p, fp, D)
            N = new_block(M, B)
            nC, nE = counts(Fp, co)
            ap_C = p + _sage_const_1  - nC
            c1 = (ZZ(M.trace()) - ap_C) % p == _sage_const_0 
            # stable rank of the semilinear operator on the new part
            srank = (N**(_sage_const_3  * N.nrows())).rank() if N.nrows() else _sage_const_0 
            anum = N.nrows() - N.rank()
            row = dict(p=p, name=nm, blind=blindness, D=D, C1=c1, outside=len(outside),
                       Nzero=(N == _sage_const_0 ), Nrank=N.rank(), srank=srank, anum=anum,
                       trM=ZZ(M.trace()), apC=ap_C)
            if do_c5 and p <= C5_PRIME_CAP:
                F2 = GF(p**_sage_const_2 , 'g')
                nC2, nE2 = counts(F2, co)
                b1 = nE - nC
                s2C = p**_sage_const_2  + _sage_const_1  - nC2; s2E = p**_sage_const_2  + _sage_const_1  - nE2
                b2 = (b1**_sage_const_2  - (s2C - s2E)) / _sage_const_2 
                assert b2 in ZZ
                b2 = ZZ(b2)
                ss_pc = (b1 % p == _sage_const_0 ) and (b2 % p == _sage_const_0 )
                row.update(b1=b1, b2=b2, ss_pointcount=ss_pc,
                           C5=(ss_pc == (srank == _sage_const_0 )))
            if do_c3:
                ok3, gen, got = c3_divisors(p, co, D)
                row.update(C3=ok3, genus=gen)
            rows.append(row)
            log.append(("ROW", name, row))
            print("[%s] p=%-5d %-26s %-8s C1=%s C3=%s C5=%s | Nzero=%s rank=%d srank=%d a=%d%s"
                  % (name, p, nm, blindness,
                     "ok" if c1 else "FAIL",
                     ("ok" if row.get("C3") else "FAIL") if do_c3 else "-",
                     ("ok" if row.get("C5") else "FAIL") if "C5" in row else "-",
                     row["Nzero"], row["Nrank"], srank, anum,
                     ("  b1=%d b2=%d ssPC=%s" % (row["b1"], row["b2"], row["ss_pointcount"]))
                     if "b1" in row else ""))
    return rows

